import pandas as pd
import json

# Load data
df = pd.read_csv('/app/benchmark/data.csv')
df['Decade'] = (df['Year'] // 10) * 10

# Era analysis details
def get_era(year):
    if year <= 1960:
        return "Golden Age (1934–1960)"
    elif year <= 1980:
        return "Silver Age (1961–1980)"
    elif year <= 2000:
        return "Modern Era (1981–2000)"
    else:
        return "Contemporary Era (2001–2026)"

df['Era'] = df['Year'].apply(get_era)

# Decade details: composers and their wins per decade
decade_details = {}
for decade, group in df.groupby('Decade'):
    composers = group['Composer'].value_counts().to_dict()
    decade_details[int(decade)] = {
        'years': sorted(group['Year'].tolist()),
        'composers': composers,
        'unique': len(composers),
        'total': len(group)
    }

# Era details
era_details = {}
for era, group in df.groupby('Era'):
    composers = group['Composer'].value_counts().to_dict()
    era_details[era] = {
        'years': sorted(group['Year'].tolist()),
        'composers': composers,
        'unique': len(composers),
        'total': len(group)
    }

# Full composer timeline
composer_timeline = {}
for _, row in df.iterrows():
    c = row['Composer']
    if c not in composer_timeline:
        composer_timeline[c] = []
    composer_timeline[c].append({
        'year': int(row['Year']),
        'film': row['Film']
    })

# Save detailed data
with open('/app/output/decade_details.json', 'w') as f:
    json.dump(decade_details, f, indent=2)

with open('/app/output/era_details.json', 'w') as f:
    json.dump(era_details, f, indent=2)

with open('/app/output/composer_timeline.json', 'w') as f:
    json.dump(composer_timeline, f, indent=2)

print("Detailed data saved.")

# Print some narrative data
print("\n=== Decade-by-decade breakdown ===")
for d in sorted(decade_details.keys()):
    info = decade_details[d]
    print(f"\n{d}s: {info['unique']} unique composers across {info['total']} ceremonies")
    for comp, wins in info['composers'].items():
        if wins > 1:
            print(f"  {comp}: {wins} wins")

print("\n=== Era breakdown ===")
for era in ["Golden Age (1934–1960)", "Silver Age (1961–1980)", "Modern Era (1981–2000)", "Contemporary Era (2001–2026)"]:
    info = era_details[era]
    print(f"\n{era}: {info['unique']} unique composers, {info['total']} wins")
    for comp, wins in info['composers'].items():
        if wins > 1:
            print(f"  {comp}: {wins} wins")

# Check for any special milestones
print("\n=== Milestones ===")
# Youngest/oldest implied: we only have ceremony years, not birth years, so skip or note limitation
print("Note: Birth years not available in dataset; cannot determine youngest/oldest winners.")

# First-time winners per decade
for d in sorted(decade_details.keys()):
    prev_decades = [x for x in decade_details.keys() if x < d]
    prev_composers = set()
    for pd in prev_decades:
        prev_composers.update(decade_details[pd]['composers'].keys())
    current_composers = set(decade_details[d]['composers'].keys())
    new_composers = current_composers - prev_composers
    print(f"{d}s first-time winners: {len(new_composers)} ({', '.join(sorted(new_composers))})")

